// ─── File: OidcLoginDemo.java ───
package com.bank.oidc;

import java.util.*;
import java.util.logging.*;

public class OidcLoginDemo {
    private static final Logger log = Logger.getLogger(OidcLoginDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OpenIdProvider provider = new OpenIdProvider("https://auth.nationalbank.example");
        RelyingParty wealthSite = new RelyingParty("wealth-site", "https://auth.nationalbank.example");

        // Login with openid scope -> provider returns an ID token with identity claims.
        String nonce = "n-" + UUID.randomUUID();
        Map<String, String> idToken = provider.issueIdToken("rajesh-001", "wealth-site", nonce);
        log.info(() -> "Provider issued ID token for sub=" + idToken.get("sub"));

        // Relying party validates and extracts identity.
        Map<String, String> identity = wealthSite.login(idToken, nonce);
        log.info(() -> "Logged in as: " + identity.get("name") + " <" + identity.get("email") + ">");

        // Wrong audience -> rejected.
        Map<String, String> wrongAud = provider.issueIdToken("rajesh-001", "other-site", nonce);
        try {
            wealthSite.login(wrongAud, nonce);
        } catch (IdTokenValidationException e) {
            log.severe("Rejected ID token (wrong audience): " + e.getMessage());
        }

        // Replay with mismatched nonce -> rejected.
        try {
            wealthSite.login(idToken, "different-nonce");
        } catch (IdTokenValidationException e) {
            log.warning("Rejected replay (nonce mismatch): " + e.getMessage());
        }
    }
}

