class IdTokenValidationException extends RuntimeException {
    IdTokenValidationException(String m) { super(m); }
}

// ─── Would be in OpenIdProvider.java ───
class OpenIdProvider {
    private final String issuer;
    private final Map<String, String[]> identities = Map.of(
        "rajesh-001", new String[]{"Rajesh Kumar", "rajesh@example.com"});
    OpenIdProvider(String issuer) { this.issuer = issuer; }

    // Returns a (simulated, already-decoded) signed ID token as claims.
    Map<String, String> issueIdToken(String sub, String audience, String nonce) {
        String[] who = identities.get(sub);
        Map<String, String> claims = new HashMap<>();
        claims.put("iss", issuer);
        claims.put("sub", sub);
        claims.put("aud", audience);
        claims.put("nonce", nonce);
        claims.put("name", who[0]);
        claims.put("email", who[1]);
        claims.put("sig", "valid"); // signature verified against JWKS in production
        return claims;
    }
}

// ─── Would be in RelyingParty.java ───
class RelyingParty {
    private final String clientId;
    private final String expectedIssuer;
    RelyingParty(String clientId, String expectedIssuer) {
            this.clientId = clientId;
            this.expectedIssuer = expectedIssuer;
    }

    Map<String, String> login(Map<String, String> idToken, String expectedNonce) {
        if (!"valid".equals(idToken.get("sig")))
            throw new IdTokenValidationException("bad signature");
        if (!expectedIssuer.equals(idToken.get("iss")))
            throw new IdTokenValidationException("untrusted issuer");
        if (!clientId.equals(idToken.get("aud")))
            throw new IdTokenValidationException("audience mismatch: " + idToken.get("aud"));
        if (!expectedNonce.equals(idToken.get("nonce")))
            throw new IdTokenValidationException("nonce mismatch (possible replay)");
        return Map.of("sub", idToken.get("sub"), "name", idToken.get("name"),
                      "email", idToken.get("email"));
    }
}

